import random


def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]

    opp_c = 0
    for x in op:
        if x == 'C':
            opp_c += 1
    opp_d = n - opp_c
    opp_rate = opp_c / float(n)

    last_op = op[-1]
    last_me = me[-1]

    # Endgame: last few rounds, exploit unless opponent is very cooperative
    if n >= 98:
        if opp_rate > 0.95 and opp_d == 0:
            return 'C'
        return 'D'

    if n >= 93:
        if opp_rate > 0.9 and opp_d <= 1:
            return 'C'
        return 'D'

    # Detect near-pure cooperator: exploit while keeping them cooperating.
    if n >= 10 and opp_rate >= 0.9 and opp_d <= 1:
        # Mostly defect, but occasionally cooperate to reset their goodwill
        # and avoid locking into a punishment spiral.
        if rng.random() < 0.8:
            return 'D'
        return 'C'

    # Detect pure defector.
    if n >= 8 and opp_c == 0:
        # Defect almost always; probe rarely to see if they adapt.
        if rng.random() < 0.03 and n < 90:
            return 'C'
        return 'D'

    # Detect mostly-defecting opponent.
    if n >= 10 and opp_rate < 0.2:
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # Count recent behavior (window adapts to game phase)
    w = 10
    if n < w:
        w = n
    recent_op = op[-w:]
    recent_me = me[-w:]
    recent_opp_c = 0
    for x in recent_op:
        if x == 'C':
            recent_opp_c += 1
    recent_my_c = 0
    for x in recent_me:
        if x == 'C':
            recent_my_c += 1

    # Compute current opponent defection run and cooperation run
    run_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            run_d += 1
        else:
            break
    run_c = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'C':
            run_c += 1
        else:
            break

    # Long defection streak: retaliate firmly but occasionally probe
    if run_d >= 3:
        if rng.random() < 0.85:
            return 'D'
        return 'C'

    # Long cooperation streak with mostly-cooperative opponent:
    # keep cooperating, with very rare exploitation near the end.
    if run_c >= 5 and opp_rate > 0.75:
        if n > 60 and rng.random() < 0.06:
            return 'D'
        return 'C'

    # If opponent is mostly cooperative but just defected, forgive quickly
    # unless it's part of a run.
    if last_op == 'D':
        if opp_rate > 0.7 and run_d == 1:
            # forgive, but not too often
            if rng.random() < 0.6:
                return 'C'
            return 'D'
        if opp_rate > 0.55:
            if rng.random() < 0.3:
                return 'C'
            return 'D'
        return 'D'

    # Opponent just cooperated.
    # If we've been defecting a lot, restore cooperation to recover mutual CC.
    if last_me == 'D':
        if recent_my_c <= w // 2:
            return 'C'
        if opp_rate > 0.5:
            return 'C'
        # against less cooperative opponents, keep the pressure
        if rng.random() < 0.5:
            return 'D'
        return 'C'

    # Both cooperated last round.
    # If opponent is consistently cooperative, occasionally test for exploitation
    # but only when the opponent has strong cooperative history.
    if opp_rate > 0.8 and recent_opp_c >= w - 1:
        if n > 30 and n < 90 and rng.random() < 0.05:
            return 'D'
        return 'C'

    # Mixed opponent: retaliate against defections, reward cooperation gently.
    if last_op == 'C':
        if rng.random() < 0.08 and n < 90:
            return 'D'
        return 'C'

    return 'C'
